function normalAnimal(a,index=0){obj(a,'Animal');return{...copy(a),id:a.id??'animal-'+(index+1),group:a.group??'other',split:a.split??'unassigned',sex:a.sex??null,age_days:a.age_days??null,batch:a.batch??null,coverage:{...coverageDefaults(),...a.coverage},sections:(a.sections??[]).map(normalSection)};}
