 const p=study.protocol;obj(p,'Protocol');text(p.id,'protocol ID',128);text(p.version,'protocol version',64);text(p.boundary_definition,'boundary definition',20000,true);if(!['pixel-mask/1','polygon-native/1'].includes(p.measurement_profile))fail('Unsupported measurement profile.');optional(p.maximum_gap_um,'maximum gap',true);
