function getAnimal(study,id){const a=study.animals.find(a=>a.id===id);if(!a)fail('Unknown animal: '+id);return a;}
function getSection(study,animalId,sectionId){const a=getAnimal(study,animalId),s=a.sections.find(s=>s.id===sectionId);if(!s)fail('Unknown section: '+sectionId);return[a,s];}
function event(study,type,detail,modify){validate(study);if(study.history.length>=LIMITS.history)fail('History is full; export the current study before continuing.');const next=copy(study);modify(next);next.history.push({type,at:new Date().toISOString(),detail:copy(detail)});validate(next);return freeze(next);}
