async function importStudy(input){const parsed=typeof input==='string'?JSON.parse(input):input;if(parsed.schema!==SCHEMA)fail('Unsupported study schema.');const study=create(parsed);for(const a of study.animals)for(const s of a.sections)if(s.review&&await reviewStatus(study,a.id,s.id)!=='approved')fail('Study contains a stale or altered approval: '+a.id+'/'+s.id);return study;}
async function exportStudy(study){validate(study);for(const a of study.animals)for(const s of a.sections)if(s.review&&await reviewStatus(study,a.id,s.id)!=='approved')fail('Study contains a stale approval.');return copy(study);}
